<?php
require_once __DIR__ . '/../config/config.php';require_once __DIR__ . '/../includes/functions.php';require_login();if(is_admin())redirect('admin/dashboard.php');$id=(int)($_GET['course_id']??0);$st=$pdo->prepare("SELECT c.* FROM courses c JOIN enrollments e ON e.course_id=c.id WHERE c.id=? AND e.user_id=? AND e.status='approved'");$st->execute([$id,current_user()['id']]);$course=$st->fetch();if(!$course){http_response_code(403);exit('You must have an approved enrollment to access this course.');}$q=$pdo->prepare('SELECT * FROM lessons WHERE course_id=? ORDER BY sort_order,id');$q->execute([$id]);$lessons=$q->fetchAll();$lessonId=(int)($_GET['lesson_id']??($lessons[0]['id']??0));$current=null;foreach($lessons as $l){if((int)$l['id']===$lessonId){$current=$l;break;}}page_header('Learning: '.$course['title']);?><p><a href="<?=e(BASE_URL)?>/student/dashboard.php">← My dashboard</a></p><h1><?=e($course['title'])?></h1><div class="grid" style="grid-template-columns:minmax(0,2fr) minmax(230px,1fr)"><section class="panel"><?php if($current):?><h2><?=e($current['title'])?></h2><?php if($current['description']):?><p><?=nl2br(e($current['description']))?></p><?php endif;?><video class="video" controls controlsList="nodownload" preload="metadata"><source src="<?=e(BASE_URL.'/'.$current['video_path'])?>">Your browser does not support video playback.</video><?php else:?><p>No lessons have been added yet.</p><?php endif;?></section><aside class="panel"><h3>Course lessons</h3><?php foreach($lessons as $l):?><p><a href="<?=e(BASE_URL)?>/student/learn.php?course_id=<?=$id?>&lesson_id=<?=(int)$l['id']?>"><?=e($l['title'])?></a></p><?php endforeach;?></aside></div><?php page_footer();?>
